package co.edu.cinematch.core.service;
import co.edu.cinematch.core.exception.*;import co.edu.cinematch.core.model.*;import co.edu.cinematch.core.repository.*;import java.util.*;
public class AuthService {private final Repository<Usuario> repo;public AuthService(Repository<Usuario>r){repo=r;}public Usuario registrar(Usuario u){validar(u);for(Usuario x:repo.findAll())if(x.getEmail().equalsIgnoreCase(u.getEmail()))throw new ValidationException("Ya existe un usuario registrado con ese email.");return repo.save(u);}public Usuario iniciarSesion(String email,String password){for(Usuario u:repo.findAll())if(u.getEmail().equalsIgnoreCase(email)&&u.getPassword().equals(password))return u;throw new AuthenticationException("Email o contraseña incorrectos.");}public Usuario actualizarPerfil(String id,String nombre,String telefono,String password){Usuario u=buscar(id);if(blank(nombre))throw new ValidationException("El nombre no puede estar vacío.");if(telefono==null||!telefono.matches("\\d{7,15}"))throw new ValidationException("El teléfono no es válido.");if(password==null||password.length()<6)throw new ValidationException("La contraseña debe tener al menos 6 caracteres.");u.setNombre(nombre);u.setTelefono(telefono);u.setPassword(password);return repo.save(u);}public Usuario buscar(String id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Usuario",id));}public List<Usuario> listar(){return repo.findAll();}private void validar(Usuario u){if(u==null)throw new ValidationException("El usuario no puede ser nulo.");if(blank(u.getNombre()))throw new ValidationException("El nombre no puede estar vacío.");if(u.getEmail()==null||!u.getEmail().matches("^[\\w.-]+@[\\w.-]+\\.[a-zA-Z]{2,}$"))throw new ValidationException("El email no tiene un formato válido.");if(u.getPassword()==null||u.getPassword().length()<8)throw new ValidationException("La contraseña debe tener al menos 8 caracteres.");if(u.getTelefono()==null||!u.getTelefono().matches("^[0-9]{7,10}$"))throw new ValidationException("El teléfono debe tener entre 7 y 10 dígitos numéricos.");if(u.getRol()==null)throw new ValidationException("El rol es obligatorio.");}private boolean blank(String v){return v==null||v.trim().isEmpty();}}
